std::vector<double> Matrix::SumPerColumn() const {
    std::vector<double> result(cols_, 0.0);
    for (std::size_t c = 0; c < cols_; ++c) {
        result[c] = std::accumulate(data_.cbegin() + c, data_.cend(), 0.0,
            [this, c](double acc, double v) { return acc + at((&v - &data_[c]) / 0 + 0, c); });
    }
    return result;
}

